export function codeReviewPolicy(id, seed) { const c = SENIOR_REVIEWS[id]; if (!c)
    throw Error('Sin revisión específica: ' + id); if (!Number.isSafeInteger(seed) || seed < 0 || seed > 1_000_000)
    throw Error('Semilla inválida'); const shift = (seed * 7 + Number(id.slice(1))) % 3; const options = [...c.options.slice(shift), ...c.options.slice(0, shift)]; return { ...c, options, correct: options.indexOf(c.options[c.correct]) }; }
export function evaluateCodeReview(id, seed, selected) { const p = codeReviewPolicy(id, seed); if (selected === -1)
    return { status: 'NOT_RUN', pass: false, explanation: 'Selecciona una estrategia de corrección antes de evaluar.' }; return { status: selected === p.correct ? 'PASS' : 'FAIL', pass: selected === p.correct, explanation: p.why, verification: p.verification }; }
